/**
 *
 * @param {Object} sheet
 * @param {String} rangeCell
 * @returns Cell[] References
 *
 * sample usage
 * const row = selectRange(worksheet, `A${lastRow}:C${lastRow + 4}`);
 * row.forEach(cell => {
   // TODO: Do something with each cell
 *});
 */
const selectRange = (sheet, rangeCell) => {
  let [startCell, endCell] = rangeCell.split(':')

  // Recalculate in case bottom left and top right are given
  if (endCell < startCell) {
    let temp = endCell
    endCell = startCell
    startCell = temp
  }

  let [endCellColumn, endRow] = endCell.match(/[a-z]+|[^a-z]+/gi)
  let [startCellColumn, startRow] = startCell.match(/[a-z]+|[^a-z]+/gi)

  // Recalculate in case bottom left and top right are given
  if (endCellColumn < startCellColumn) {
    let temp = endCellColumn
    endCellColumn = startCellColumn
    startCellColumn = temp
  }

  // Recalculate in case bottom left and top right are given
  if (endRow < startRow) {
    let temp = endRow
    endRow = startRow
    startRow = temp
  }

  let endColumn = sheet.getColumn(endCellColumn)
  let startColumn = sheet.getColumn(startCellColumn)

  if (!endColumn) throw new Error('End column not found')
  if (!startColumn) throw new Error('Start column not found')

  const endColumnNumber = endColumn.number
  const startColumnNumber = startColumn.number

  const cells = []
  for (let y = parseInt(startRow); y <= parseInt(endRow); y++) {
    const row = sheet.getRow(y)

    for (let x = startColumnNumber; x <= endColumnNumber; x++) {
      cells.push(row.getCell(x))
    }
  }
  return cells
}

/**
 * Applies an outer border to a specified range of cells on a given sheet.
 *
 * @param {Object} sheet - The sheet object on which the border ncreateOuterBordereeds to be applied.
 * @param {string} rangeCell - The cell range in the format 'A1:B2' where the outer border needs to be applied.
 * @param {string} [borderWidth='medium'] - The width of the border. Default is 'medium'.
 *
 * @throws {Error} If end column or start column is not found in the sheet.
 *
 * @example
 * const sheet = workbook.addWorksheet('Sheet 1');
 * createOuterBorder(sheet, 'A1:D4', 'thick');
 */
const createOuterBorder = (sheet, rangeCell, borderWidth = 'medium') => {
   let [startCell, endCell] = rangeCell.split(':')

    // Recalculate in case bottom left and top right are given
    if (endCell < startCell) {
      let temp = endCell
      endCell = startCell
      startCell = temp
    }

    let [endCellColumn, endRow] = endCell.match(/[a-z]+|[^a-z]+/gi)
    let [startCellColumn, startRow] = startCell.match(/[a-z]+|[^a-z]+/gi)

    // Recalculate in case bottom left and top right are given
    if (endCellColumn < startCellColumn) {
      let temp = endCellColumn
      endCellColumn = startCellColumn
      startCellColumn = temp
    }

    // Recalculate in case bottom left and top right are given
    if (endRow < startRow) {
      let temp = endRow
      endRow = startRow
      startRow = temp
    }

    let endColumn = sheet.getColumn(endCellColumn)
    let startColumn = sheet.getColumn(startCellColumn)

    if (!endColumn) throw new Error('End column not found')
    if (!startColumn) throw new Error('Start column not found')

    const endColumnNumber = endColumn.number
    const startColumnNumber = startColumn.number

    const borderStyle = {
        style: borderWidth
    };
    for (let i = parseInt(startRow); i <= parseInt(endRow); i++) {
        const leftBorderCell = sheet.getCell(i, startColumnNumber);
        const rightBorderCell = sheet.getCell(i, endColumnNumber);
        leftBorderCell.border = {
            ...leftBorderCell.border,
            left: borderStyle
        };
        rightBorderCell.border = {
            ...rightBorderCell.border,
            right: borderStyle
        };
    }

    for (let i = startColumnNumber; i <= endColumnNumber; i++) {
        const topBorderCell = sheet.getCell(parseInt(startRow), i);
        const bottomBorderCell = sheet.getCell(parseInt(endRow), i);
        topBorderCell.border = {
            ...topBorderCell.border,
            top: borderStyle
        };
        bottomBorderCell.border = {
            ...bottomBorderCell.border,
            bottom: borderStyle
        };
    }
};

/**
 * Returns an array of date ranges (start and end dates) for each month between the given start and end dates.
 *
 * @param {string} start_date - The start date in the format "YYYY-MM-DD".
 * @param {string} end_date - The end date in the format "YYYY-MM-DD".
 * @returns {Array.<{start: string, end: string}>} - An array of objects, where each object has `start` and `end` properties that represent the start and end dates of a month, respectively.
 *
 * @example
 * // Returns [{start: '2022-01-01', end: '2022-01-31'}, {start: '2022-02-01', end: '2022-02-28'}]
 * getMonthsBetweenDates('2022-01-01', '2022-02-28');
 */
function getMonthsBetweenDates(start_date, end_date) {
    let dates = [];
    let startDate = new Date(start_date);
    const endDate = new Date(end_date);

    while (startDate <= endDate) {
        let year = startDate.getFullYear();
        let month = startDate.getMonth();
        let monthEnd = new Date(year, month + 1, 0); // 当月の最終日
        if (monthEnd > endDate) {
            monthEnd = endDate;
        }
        if(startDate <= monthEnd) {
            dates.push({
                start: startDate.toISOString().split('T')[0],
                end: monthEnd.toISOString().split('T')[0]
            });
        }
        startDate = new Date(year, month + 1, 1);
    }

    return dates;
}

