            onSuccess: (retrievedData) => {
                if (!retrievedData || Number.isNaN(retrievedData)) {
                    reject(new Error('Retrieved data is missing or in an unexpected format.'));
                } else {
                    resolve(retrievedData);
                }
            },
            onError: (error) => {
                reject(error);
            }
        });
    });

    if (data.length > 0 && data[0].hasOwnProperty('mg_original_paid')) {
        updateCellWithFormat(sheet,`G:13`,  data[0].mg_original_paid);
    } else {
        console.warn('Original paid data is missing or in an unexpected format.');
    }
    return parseFloat(data[0].mg_original_paid)
}


const mgBalanceData = async (start_date, end_date) => {
    return new Promise(async (resolve, reject) => {
        try {
            await setDateMgBalanceParams.setValue({ start_date, end_date });
            mgBalanceDataForReport.trigger({
                onSuccess: (data) => {
                    if (!data || !data['0'] || isNaN(data['0'].prior_royalty_due) || isNaN(data['0'].current_royalty_due)) {
                        reject('Invalid data received');
                    } else {
                        resolve(data);
                    }
                },
                onError: (error) => {
                    reject(error);
                }
            });
        } catch (error) {
            reject(error);
        }
    });
};



const updateCellWithFormat = (sheet, position, value, format = '#,##0.00') => {
    const cell = sheet.getCell(position);
    cell.value = parseFloat(value.toFixed(2));
    cell.numFmt = format;
};

/**
 * Fetches and calculates the sum of royalties for a given period and updates the specified sheet.
 *
 * @param {Object} sheet - The sheet object to update.
 * @param {string} start_date - The start date of the period.
 * @param {string} end_date - The end date of the period.
 * @param originalPaid
 * @param {number} len_items - The length of items to determine where to place the results in the sheet.
 * @returns {Promise<void>} A promise that resolves when the operation is complete.
 * @throws Will throw an error if the data fetching fails or returns invalid data.
 *
 * @example
 *
 * const sheet = ...; // your sheet object
 * const start_date = "2023-01-01";
 * const end_date = "2023-01-31";
 * const len_items = 10;
 *
 * addSumRoyaltyPervPeriod(sheet, start_date, end_date, len_items)
 *     .then(() => {
 *         console.log("Sheet updated successfully!");
 *     })
 *     .catch(error => {
 *         console.error("An error occurred:", error);
 *     });
 */
const addSumRoyaltyPervPeriod = async (sheet, start_date, end_date, originalPaid, len_items) => {
    const data = await mgBalanceData(start_date, end_date);
    console.log(data);
    const contractData = data.find(r => r.contract_id === contract_royalty_report.value);
    console.log(contractData);

    const sumRoyaltyDuePervPeriod = contractData.prior_royalty_due + contractData.prior_royalty_adjustment;
    const sumRoyaltyThisPeriod = contractData.current_royalty_due;
    const initMgBeginningBalance = contractData.mg_beginning_balance;
    const adjustmentRoyaltyDue = contractData.current_royalty_adjustment;
    const adjustedRoyaltySum = originalPaid - initMgBeginningBalance + sumRoyaltyDuePervPeriod + adjustmentRoyaltyDue;
    const sumRoyaltyDueAllPeriod = adjustedRoyaltySum + sumRoyaltyThisPeriod;
    const current_mg_balance = contractData.current_mg_balance;

    updateCellWithFormat(sheet, `G14`, adjustedRoyaltySum);
    updateCellWithFormat(sheet, `G15`, sumRoyaltyThisPeriod);
    updateCellWithFormat(sheet, `G16`, sumRoyaltyDueAllPeriod);

    if (current_mg_balance <= 0) {
        sheet.getCell(`G17`).value = '-';
    } else {
        updateCellWithFormat(sheet, `G17`, current_mg_balance);
    }
}


