function add_titles(sheet, end_date) {

  sheet.getCell('B1').value = 'Licensor:';
  sheet.getCell('B2').value = 'Licensee:';
  sheet.getCell('B3').value = 'Title:';
  sheet.getCell('B3').alignment = { vertical: 'top' };
  sheet.getCell('B5').value = 'Territories:';
  sheet.getCell('B6').value = 'Release Date:';
  sheet.getCell('B7').value = 'Report Ending Dates:';

  sheet.getCell('C1').value = get_licensor_name();
  sheet.getCell('C2').value = 'NIS America, Inc.'
  sheet.getCell('C3').value = get_game_titles_for_royalty_report.data;
  sheet.getCell('C3').alignment = { wrapText: true };
  //sheet.mergeCells('C3:D4');
  sheet.getCell('C7').value = new Date(end_date);

  selectRange(sheet, 'B1:B8').forEach(cell => {
    cell.alignment = { horizontal: 'right' };
  });
