/**
 * @param {object} sheet
 * @param inventory
 */

function add_values(sheet, inventory){
  for(let i=0; i < inventory.values.length; i++){
    sheet.getCell(inventory.values[i].cell).value = inventory.values[i].value;
  }
}

function addUnitsSold(sheet, start_date, end_date, len_items, items) {
  const physicalQuantity = getSumByTitle(items, '[Pp]hysical|[Gg]oods', 'sold_quantity');
  const digitalQuantity = getSumByTitle(items, 'Digital*', 'sold_quantity');

  sheet.getCell(`G9`).value = physicalQuantity;
  sheet.getCell(`G10`).value = digitalQuantity;
}

const getSumByTitle = (items, regex, field) => {
  let sum = 0;
  const regexExp = new RegExp(regex, 'i');
  for (let i = 0; i < items.length; i++) {
    if(regexExp.test(items[i].game_type.replace(/[\s:]/g))) {
      sum += items[i][field];
    }
  }
  return sum;
}

/**
 * @param {object} sheet
 * @param inventory
 */
function add_fonts(sheet, inventory){
  for(let i=0; i < inventory.fonts.length; i++){
    if(inventory.fonts[i].cell.includes(':')){
      selectRange(sheet, inventory.fonts[i].cell).forEach(c => {
        c.font = { italic: !!inventory.fonts[i].italic };
      });
      continue;
    }
    sheet.getCell(inventory.fonts[i].cell).font = {
      bold: !!inventory.fonts[i].bold,
      italic: !!inventory.fonts[i].italic
    }
  }
}

/**
 * @param {object} sheet
 * @param inventory
 */
function add_fills(sheet, inventory){
  for(let i=0; i < inventory.fills.length; i++){
    if(inventory.fills[i].cell.includes(':')){
      selectRange(sheet, inventory.fills[i].cell).forEach(c => {
        c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: inventory.fills[i].fgColor }};
      });
      continue;
    }
    sheet.getCell(inventory.fills[i].cell).fill = {
      type: 'pattern', pattern: 'solid', fgColor: {argb: inventory.fills[i].fgColor }
    }
  }
}

/**
 * @param {object} sheet
 * @param inventory
 */
function add_alignments(sheet, inventory){
  for(let i=0; i < inventory.alignments.length; i++){
    if(inventory.alignments[i].cell.includes(':')){
      selectRange(sheet, inventory.alignments[i].cell).forEach(c => {
        c.alignment = { horizontal: inventory.alignments[i].horizontal };
      });
      continue;
    }
    sheet.getCell(inventory.alignments[i].cell).alignment = {
       horizontal: inventory.alignments[i].horizontal
    }
  }
}

/**
 * Adds summary list to the sheet.
 *
 * @param {object} sheet - The sheet object where data will be added.
 * @param {string} start_date - The start date of the period.
 * @param {string} end_date - The end date of the period.
 * @param {number} len_items - The length of items.
 * @param {object} items
 */
async function add_summary_list(sheet, start_date, end_date, len_items, items) {
    // Async operations
    try {
        addUnitsSold(sheet, start_date, end_date, len_items, items);
        const originalPaid = await addOriginalPaid(sheet, len_items);
        await addSumRoyaltyPervPeriod(sheet, start_date, end_date, originalPaid, len_items);
    } catch (error) {
        console.error("An error occurred while adding summary list:", error);
    }
    const summaryData = summary_inventory(len_items);
        // Add values, fonts, fills, etc.
    add_values(sheet, summaryData);
    add_fonts(sheet, summaryData);
    add_fills(sheet, summaryData);
    add_alignments(sheet, summaryData);
    add_summary_layout(sheet, len_items);
}

