    add_alignments(sheet,footer_inventory(len_items));
}


async function exportReport() {
  const dateRanges = getMonthsBetweenDates(start_date_royalty_report.value, end_date_royalty_report.value);

  for (const range of dateRanges) {
    const workbook = new ExcelJS.Workbook();  // この行をループの内部に移動
    const sheet = workbook.addWorksheet("Royalty Due");
    const adjustment_sheet = workbook.addWorksheet('Royalty Adjustment');
    sheet.columns = columnRoyaltyDueWides;
    adjustment_sheet.columns = columnAdjustmentItemWides;

    const currentStartDate = range.start;
    const currentEndDate = range.end;
    let items = [];
    let adjustmentItems = [];
    try {
        items = await getItems(currentStartDate, currentEndDate);
        adjustmentItems = await getAdjustmentItems(currentStartDate, currentEndDate);
    } catch (error) {
        console.error("Error fetching data for the date range", currentStartDate, "to", currentEndDate);
        console.error("Error details:", error);
    }

    const len_items = isNaN(items.length) ? 0 : items.length + 23;
    const len_adjustment_items = isNaN(adjustmentItems.length) ? 0 : adjustmentItems.length + 23;

    add_titles(sheet, currentEndDate);
    add_titles(adjustment_sheet, currentEndDate);

    if (len_items > 23) {
        await add_item_table(sheet, currentStartDate, currentEndDate, len_items, items);
    }
    if (len_adjustment_items > 23) {
        await add_adjustment_item_table(adjustment_sheet, currentStartDate, currentEndDate, len_adjustment_items, adjustmentItems);
    }
    await add_summary_list(sheet, currentStartDate, currentEndDate, len_items, items);
    add_footer(sheet, len_items);

    const buffer = await workbook.xlsx.writeBuffer();
    const [year, month] = currentStartDate.split('-');

    const formattedDate = `${year}_${month}`;
    await utils.downloadFile({ base64Binary: buffer.toString('base64')}, licensor_royalty_report.selectedItem.licensor_name + "_" +contract_royalty_report.selectedItem.contract_name + "_" + formattedDate, "xlsx");
  }
}


