function getPreviousDay(dateString) {
  let date = new Date(dateString);
  date.setDate(date.getDate() - 1);
  return date.toISOString().split('T')[0];
}

function calculateMonthBoundaries(maxClosedYearMonth) {
  const year = parseInt(maxClosedYearMonth.split('-')[0], 10);
  const month = parseInt(maxClosedYearMonth.split('-')[1], 10) - 1; // JavaScriptの月は0から始まる

  // 月の最終日を計算（UTC）
  const maxClosedEndMonth = new Date(Date.UTC(year, month + 1, 0));
  const maxClosedEndMonthString = maxClosedEndMonth.toISOString().split('T')[0];

  // 次の月の初日を計算（UTC）
  const nextMonthStartDate = new Date(Date.UTC(year, month + 1, 1));
  const nextMonthStartDateString = nextMonthStartDate.toISOString().split('T')[0];

  return {
    maxClosedEndMonthString,
    nextMonthStartDateString
  };
}

async function combineRoyaltyData(dataClosed, dataOpen) {
  return new Promise((resolve, reject) => {
    try {
      let combinedData = {};

      // dataClosed の処理
      dataClosed.forEach(item => {
        const key = item.licensor_id + '_' + item.contract_id;
        combinedData[key] = { ...item }; // スプレッド構文でオブジェクトをコピー
      });

      // dataOpen の処理
      dataOpen.forEach(item => {
        const key = item.licensor_id + '_' + item.contract_id;
        if (combinedData[key]) {
          // 合計を計算
          combinedData[key].sum_royalty_due += item.sum_royalty_due;
        } else {
          combinedData[key] = { ...item }; // 存在しない場合は新しいエントリを作成
        }
      });

      resolve(Object.values(combinedData));
    } catch (error) {
      reject(error);
    }
  });
}

async function calculateRoyaltyDueForContracts(startDate, endDate) {
  const systemStartDate = '2022-07-01';
  const maxClosedYearMonth = max_closed_year_month.data[0].max_year_month;
  const endDateLastMonth = getPreviousDay(startDate);
  console.log(systemStartDate,startDate, endDate,endDateLastMonth, maxClosedYearMonth);

  let priorRoyaltyDue, priorRoyaltyAdjustment, currentRoyaltyDue, currentRoyaltyAdjustment;

  if (maxClosedYearMonth + '-01' >= startDate) {
    // 1. maxClosedYearMonth+'-01' >= startDateの場合
        console.log('pattern1')
    priorRoyaltyDue = await getRoyaltyDueFromClosedMonth(systemStartDate, endDateLastMonth);
    priorRoyaltyAdjustment = await getRoyaltyAdjustment(systemStartDate, endDateLastMonth);
    currentRoyaltyDue = await getRoyaltyDueFromClosedMonth(startDate, endDate);
    currentRoyaltyAdjustment = await getRoyaltyAdjustment(startDate, endDate);
    await isClosedMonthStatus.setValue(true);
  } else if (maxClosedYearMonth === endDateLastMonth.substring(0, 7)) {
    // 2. maxClosedYearMonth+'-01' < startDate かつ、startDateの前の月がmaxClosedYearMonthと一致する場合
    console.log('pattern2')
    priorRoyaltyDue = await getRoyaltyDueFromClosedMonth(systemStartDate, endDateLastMonth);
    priorRoyaltyAdjustment = await getRoyaltyAdjustment(systemStartDate, endDateLastMonth);
    currentRoyaltyDue = await getRoyaltyDueFromOpenMonth(startDate, endDate);
    currentRoyaltyAdjustment = await getRoyaltyAdjustment(startDate, endDate);
    await isClosedMonthStatus.setValue(false);
  } else {
    // 3. maxClosedYearMonth+'-01' < startDate かつ、startDateの前の月がmaxClosedYearMonthよりも大きい場合
        console.log('pattern3')
    const { maxClosedEndMonthString, nextMonthStartDateString } = calculateMonthBoundaries(maxClosedYearMonth);

    console.log(maxClosedEndMonthString, nextMonthStartDateString);
    // maxClosedYearMonth+'-01' < startDate の場合の priorRoyaltyDue の計算
    const priorRoyaltyDueClosed = await getRoyaltyDueFromClosedMonth(systemStartDate, maxClosedEndMonthString);
    const priorRoyaltyDueOpen = await getRoyaltyDueFromOpenMonth(nextMonthStartDateString, endDateLastMonth);

    priorRoyaltyDue = await combineRoyaltyData(priorRoyaltyDueClosed, priorRoyaltyDueOpen);
    priorRoyaltyAdjustment = await getRoyaltyAdjustment(systemStartDate, endDateLastMonth);
    currentRoyaltyDue = await getRoyaltyDueFromOpenMonth(startDate, endDate);
    currentRoyaltyAdjustment = await getRoyaltyAdjustment(startDate, endDate);
    await isClosedMonthStatus.setValue(false);
  }

  let aggregatedData = {};

  let licensorAndContractData = await getLicensorAndContractData();
  licensorAndContractData.forEach(item => {
    const key = item.licensor_id + '_' + item.contract_id;
    aggregatedData[key] = {
      licensor_id: item.licensor_id,
      licensor_name : item.licensor_name,
      contract_id: item.contract_id,
      contract_name: item.contract_name,
      mg_original_paid: item.mg_original_paid,
      mg_beginning_balance: item.mg_beginning_balance,
      prior_royalty_due: 0,
      prior_royalty_adjustment: 0,
      current_royalty_due: 0,
      current_royalty_adjustment: 0
    };
  });

  priorRoyaltyDue.forEach(item => {
    const key = item.licensor_id + '_' + item.contract_id;
    if (aggregatedData[key]) {
      aggregatedData[key].prior_royalty_due = item.sum_royalty_due;
    }else{
      aggregatedData[key] = {
        licensor_id: item.licensor_id,
        licensor_name : item.licensor_name,
        contract_id: item.contract_id,
        contract_name: item.contract_name,
        mg_original_paid: item.mg_original_paid,
        mg_beginning_balance: item.mg_beginning_balance ,
        prior_royalty_due: item.sum_royalty_due,
        prior_royalty_adjustment: 0,
        current_royalty_due: 0,
        current_royalty_adjustment: 0
      };
    }
  });

  priorRoyaltyAdjustment.forEach(item => {
    const key = item.licensor_id + '_' + item.contract_id;
    if (aggregatedData[key]) {
      aggregatedData[key].prior_royalty_adjustment = item.sum_royalty_due;
    }else{
      aggregatedData[key] = {
        licensor_id: item.licensor_id,
      licensor_name : item.licensor_name,
      contract_id: item.contract_id,
      contract_name: item.contract_name,
      mg_original_paid: item.mg_original_paid,
        mg_beginning_balance: item.mg_beginning_balance,
        prior_royalty_due: 0, // priorRoyaltyDueで出力されなかったcontractなので0
        prior_royalty_adjustment: item.sum_royalty_due,
        current_royalty_due: 0,
        current_royalty_adjustment: 0
      };
    }
  });

  currentRoyaltyDue.forEach(item => {
    const key = item.licensor_id + '_' + item.contract_id;
    if (aggregatedData[key]) {
      aggregatedData[key].current_royalty_due = item.sum_royalty_due;
    }else{
      aggregatedData[key] = {
        licensor_id: item.licensor_id,
      licensor_name : item.licensor_name,
      contract_id: item.contract_id,
      contract_name: item.contract_name,
      mg_original_paid: item.mg_original_paid,
        mg_beginning_balance: item.mg_beginning_balance ,
        prior_royalty_due: 0, // priorRoyaltyDueで出力されなかったcontractなので 0
        prior_royalty_adjustment: 0, // priorRoyaltyAdjustmentで出力されなかったcontractなので 0
        current_royalty_due: item.sum_royalty_due, // currentRoyaltyDueで出力されなかったcontractなので 0
        current_royalty_adjustment: 0
      };
    }
  });

  currentRoyaltyAdjustment.forEach(item => {
    const key = item.licensor_id + '_' + item.contract_id;
    if (aggregatedData[key]) {
      aggregatedData[key].current_royalty_adjustment = item.sum_royalty_due;
    }else{
      aggregatedData[key] = {
        licensor_id: item.licensor_id,
      licensor_name : item.licensor_name,
      contract_id: item.contract_id,
      contract_name: item.contract_name,
      mg_original_paid: item.mg_original_paid,
        mg_beginning_balance: item.mg_beginning_balance ,
        prior_royalty_due: 0, // priorRoyaltyDueで出力されなかったcontractなので 0
        prior_royalty_adjustment: 0, // priorRoyaltyAdjustmentで出力されなかったcontractなので 0
        current_royalty_due: 0, // currentRoyaltyDueで出力されなかったcontractなので 0
        current_royalty_adjustment: item.sum_royalty_due
      };
    }
  });

  return Object.values(aggregatedData);
}

async function calculateMGForContracts(startDate, endDate) {
  console.log(startDate, endDate);
  let royaltyData = await calculateRoyaltyDueForContracts(startDate, endDate);

  let mgData = royaltyData.map(item => {
    let priorMG = item.mg_beginning_balance - item.prior_royalty_due - item.prior_royalty_adjustment;
    priorMG = priorMG < 0 ? 0 : priorMG;

    let currentMG = priorMG - item.current_royalty_due - item.current_royalty_adjustment;
    currentMG = currentMG < 0 ? 0 : currentMG;

    return {
      licensor_id: item.licensor_id,
      licensor_name : item.licensor_name,
      contract_id: item.contract_id,
      contract_name: item.contract_name,
      mg_original_paid: item.mg_original_paid,
      mg_beginning_balance : item.mg_beginning_balance,
      prior_royalty_due: item.prior_royalty_due,
      prior_royalty_adjustment : item.prior_royalty_adjustment,
      prior_mg_balance: parseFloat(priorMG.toFixed(2)),
      current_royalty_due : item.current_royalty_due,
      current_royalty_adjustment : item.current_royalty_adjustment,
      current_mg_balance: parseFloat(currentMG.toFixed(2))
    };
  });

  return mgData;
}

